// 注册
async function handleRegister() {
  // 表单验证
  if (enableMobileRegister.value) {
    // 手机号注册验证
    if (!formData.value.mobile) {
      toast.warning(t('register.enterPhone'))
      return
    }
    // 手机号格式验证
    const phoneRegex = /^1[3-9]\d{9}$/
    if (!phoneRegex.test(formData.value.mobile)) {
      toast.warning(t('register.enterPhone'))
      return
    }
    if (!formData.value.mobileCaptcha) {
      toast.warning(t('register.enterCode'))
      return
    }
  }
  else {
    // 用户名注册验证
    if (!formData.value.username) {
      toast.warning(t('register.enterUsername'))
      return
    }
  }

  if (!formData.value.password) {
    toast.warning(t('register.enterPassword'))
    return
  }

  if (!formData.value.confirmPassword) {
    toast.warning(t('register.confirmPassword'))
    return
  }

  if (formData.value.password !== formData.value.confirmPassword) {
    toast.warning(t('register.confirmPassword'))
    return
  }

  if (!formData.value.captcha) {
    toast.warning(t('register.enterCode'))
    return
  }

  // 检查SM2公钥是否配置
  if (!sm2PublicKey.value) {
    toast.warning(t('sm2.publicKeyNotConfigured'))
    return
  }

  try {
    loading.value = true

    // 加密密码
    let encryptedPassword
    try {
      // 拼接验证码和密码
      const captchaAndPassword = formData.value.captcha + formData.value.password
      encryptedPassword = sm2Encrypt(sm2PublicKey.value, captchaAndPassword)
    } catch (error) {
      console.error('Falha na criptografia de senha:', error)
      toast.warning(t('sm2.encryptionFailed'))
      return
    }

    // 构建注册数据
    const registerData = {
      username: enableMobileRegister.value ?

412fc2f58b3d.translated:
,
      captcha: formData.value.captcha,
      captchaId: formData.value.captchaId,
    })

    toast.success(t('register.captchaSendSuccess'))

    //Iniciar contagem regressiva
    smsCountdown.value = 60
    const temporizador = setInterval(() => {
      smsCountdown.value--
      if (smsCountdown.value <= 0) {
        clearInterval(temporizador)
      }
    }, 1000)
  }
  catch (erro: qualquer) {
    // Lida com erros de código de verificação - analisa códigos de erro de error.message
    if (error.message.includes('Erro de solicitação [10067]')) {
      brinde.warning(t('login.captchaError'))
    }
    //Falha ao enviar e obter novamente o código de verificação gráfica
    atualizarCaptcha()
  }
  finalmente {
    smsLoading.value = falso
  }
}

