import json
import asyncio
from typing import Dict, Any
from ..base import ToolType, ToolDefinition, ToolExecutor
from plugins_func.register import Action, ActionResponse


class DeviceIoTExecutor(ToolExecutor):
    """Executor de ferramenta IoT no lado do dispositivo"""

    def __init__(self, conn):
        self.conn = conn
        self.iot_tools: Dict[str, ToolDefinition] = {}

    async def execute(
        self, conn, tool_name: str, arguments: Dict[str, Any]
    ) -> ActionResponse:
        """Execute ferramentas IoT do lado do dispositivo"""
        if not self.has_tool(tool_name):
            return ActionResponse(
                action=Action.NOTFOUND, response=f"A ferramenta IoT {tool_name} não existe"
            )

        try:
            # Analise o nome da ferramenta e obtenha o nome do dispositivo e o tipo de operação
            if tool_name.startswith("get_"):
                # Operação de consulta: get_devicename_property
                parts = tool_name.split("_", 2)
                if len(parts) >= 3:
                    device_name = parts[1]
                    property_name = parts[2]

                    value = await self._get_iot_status(device_name, property_name)
                    if value is not None:
                        # Tratamento de modelos de resposta
                        response_success = arguments.get(
                            "response_success", "Consulta bem-sucedida: {value}"
                        )
                        response = response_success.replace("{value}", str(value))

                        return ActionResponse(
                            action=Action.RESPONSE,
                            response=response,
                        )
                    else:
                        response_failure = arguments.get(
                            "response_failure", f"Não foi possível obter o status de {device_name}"
                        )
                        return ActionResponse(
                            action=Action.ERROR, response=response_failure
                        )
            else:
                # Operação de controle: devicename_method
                parts = tool_name.split("_", 1)
                if len(parts) >= 2:
                    device_name = parts[0]
                    method_name = parts[1]

                    # 提取控制参数（排除响应参数）
                    control_params = {
                        k: v
                        for k, v in arguments.items()
                        if k not in ["response_success", "response_failure"]
                    }

                    # Envie comandos de controle IoT
                    await self._send_iot_command(
                        device_name, method_name, control_params
                    )

                    # Aguardando atualização de status
                    await asyncio.sleep(0.1)

                    response_success = arguments.get("response_success", "Operação bem-sucedida")

                    # Tratamento de espaços reservados nas respostas
                    for param_name, param_value in control_params.items():
                        placeholder = "{" + param_name + "}"
                        if placeholder in response_success:
                            response_success = response_success.replace(
                                placeholder, str(param_value)
                            )
                        if "{value}" in response_success:
                            response_success = response_success.replace(
                                "{value}", str(param_value)
                            )
                            break

                    return ActionResponse(
                        action=Action.REQLLM,
                        result=response_success,
                    )

            return ActionResponse(action=Action.ERROR, response="Não foi possível resolver o nome da ferramenta IoT")

        except Exception as e:
            response_failure = arguments.get("response_failure", "Falha na operação")
            return ActionResponse(action=Action.ERROR, response=response_failure)

