        client = None
        try:
            # Inicialize o cliente MCP do servidor
            logger.bind(tag=TAG).info(f"初始化服务端MCP客户端: {name}")
            client = ServerMCPClient(srv_config)
            # Defina o tempo limite para 10 segundos
            await asyncio.wait_for(client.initialize(logging_callback=self.logging_callback), timeout=10)

            # Usando bloqueios para proteger modificações no estado compartilhado
            async with self._init_lock:
                self.clients[name] = client
                client_tools = client.get_available_tools()
                self.tools.extend(client_tools)

        except asyncio.TimeoutError:
            logger.bind(tag=TAG).error(
                f"Failed to initialize MCP server {name}: Timeout"
            )
            if client:
                await client.cleanup()
        except Exception as e:
            logger.bind(tag=TAG).error(
                f"Failed to initialize MCP server {name}: {e}"
            )
            if client:
                await client.cleanup()

