def is_valid_image_file(file_data: bytes) -> bool:
    """Verifique se os dados do arquivo são um formato de imagem válido

    Argumentos:
        file_data: dados binários do arquivo

    Retorna:
        bool: Retorna True se for um formato de imagem válido, caso contrário retorna False"""
    # 常见图片格式的魔数（文件头）
    image_signatures = {
        b"\xff\xd8\xff": "JPEG",
        b"\x89PNG\r\n\x1a\n": "PNG",
        b"GIF87a": "GIF",
        b"GIF89a": "GIF",
        b"BM": "BMP",
        b"II*\x00": "TIFF",
        b"MM\x00*": "TIFF",
        b"RIFF": "WEBP",
    }

    # Verifique se o cabeçalho do arquivo corresponde a algum formato de imagem conhecido
    for signature in image_signatures:
        if file_data.startswith(signature):
            return True

    return False


